--
-- Name: aicrm_data_migration_run_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aicrm_data_migration_run_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.run_id IS DISTINCT FROM OLD.run_id OR NEW.adapter_id IS DISTINCT FROM OLD.adapter_id
     OR NEW.source_identity IS DISTINCT FROM OLD.source_identity
     OR NEW.source_schema_digest IS DISTINCT FROM OLD.source_schema_digest
     OR NEW.manifest_digest IS DISTINCT FROM OLD.manifest_digest
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'data migration run identity is immutable' USING ERRCODE='55000';
  END IF;
  IF OLD.phase='running' AND NEW.phase='completed' AND OLD.completed_at IS NULL
     AND NEW.completed_at IS NOT NULL AND NEW.reconciled_at IS NULL
     AND NOT EXISTS (SELECT 1 FROM public.data_migration_run_tables WHERE run_id=OLD.run_id AND NOT complete)
     AND NOT EXISTS (SELECT 1 FROM public.data_migration_run_leases WHERE run_id=OLD.run_id AND active) THEN
    RETURN NEW;
  END IF;
  IF OLD.phase='completed' AND NEW.phase='reconciled'
     AND NEW.completed_at IS NOT DISTINCT FROM OLD.completed_at
     AND OLD.reconciled_at IS NULL AND NEW.reconciled_at IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.data_migration_reconciliation_receipts WHERE run_id=OLD.run_id)
     AND NOT EXISTS (SELECT 1 FROM public.data_migration_run_leases WHERE run_id=OLD.run_id AND active) THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'invalid data migration run transition' USING ERRCODE='55000';
END $$;


--
-- Name: aicrm_ensure_customer_event_partitions(timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aicrm_ensure_customer_event_partitions(anchor timestamp with time zone, future_months integer) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  month_offset INTEGER;
  month_start TIMESTAMPTZ;
  month_end TIMESTAMPTZ;
  partition_name TEXT;
BEGIN
  IF anchor IS NULL OR future_months IS NULL OR future_months < 0 OR future_months > 36 THEN
    RAISE EXCEPTION 'invalid customer event partition request'
      USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('aicrm.customer_events.partitions', 0)
  );

  FOR month_offset IN 0..future_months LOOP
    month_start := (
      date_trunc('month', anchor AT TIME ZONE 'UTC')
      + make_interval(months => month_offset)
    ) AT TIME ZONE 'UTC';
    month_end := month_start + INTERVAL '1 month';
    partition_name := 'customer_events_' ||
      to_char(month_start AT TIME ZONE 'UTC', 'YYYY_MM');

    EXECUTE format(
      'CREATE TABLE IF NOT EXISTS public.%I PARTITION OF public.customer_events FOR VALUES FROM (%L) TO (%L)',
      partition_name,
      month_start,
      month_end
    );
  END LOOP;
END;
$$;


