    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN IF TG_OP='DELETE' OR OLD.state='completed' OR NEW.state<>'completed' OR NEW.definition_id IS DISTINCT FROM OLD.definition_id OR NEW.anonymous_digest IS DISTINCT FROM OLD.anonymous_digest OR NEW.submission_key_digest IS DISTINCT FROM OLD.submission_key_digest OR NEW.payload_digest IS DISTINCT FROM OLD.payload_digest OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'invalid public receipt transition' USING ERRCODE='55000'; END IF; RETURN NEW; END; $$;


--
-- Name: aicrm_questionnaire_receipt_transition_valid(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aicrm_questionnaire_receipt_transition_valid() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' OR OLD.state = 'completed' THEN
    RAISE EXCEPTION 'completed questionnaire operation receipts are immutable' USING ERRCODE = '55000';
  END IF;
  IF NEW.state <> 'completed' OR NEW.operation IS DISTINCT FROM OLD.operation
     OR NEW.actor_scope IS DISTINCT FROM OLD.actor_scope OR NEW.key_digest IS DISTINCT FROM OLD.key_digest
     OR NEW.payload_digest IS DISTINCT FROM OLD.payload_digest OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'invalid questionnaire operation receipt transition' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: aicrm_questionnaire_submission_count_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aicrm_questionnaire_submission_count_sync() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.questionnaires SET submission_count = submission_count + 1 WHERE id = NEW.questionnaire_id;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    UPDATE public.questionnaires SET submission_count = submission_count - 1
    WHERE id = OLD.questionnaire_id AND submission_count > 0;
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


