--
-- Name: aicrm_v1_domain_import_receipt_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aicrm_v1_domain_import_receipt_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.v1_domain_import_reconciliation_receipts
    WHERE import_version = NEW.import_version AND archive_run_id = NEW.archive_run_id
  ) THEN
    RAISE EXCEPTION 'V1 domain import is already reconciled' USING ERRCODE='55000';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.v1_archive_records
    WHERE run_id = NEW.archive_run_id AND adapter_id = NEW.adapter_id
      AND table_id = NEW.table_id AND source_key_digest = NEW.source_key_digest
      AND payload_digest = NEW.payload_digest
  ) THEN
    RAISE EXCEPTION 'V1 domain import source does not match archive' USING ERRCODE='23503';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: aicrm_v1_domain_import_reconcile_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aicrm_v1_domain_import_reconcile_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  actual_receipts BIGINT;
  actual_imported BIGINT;
  actual_archived BIGINT;
  actual_quarantined BIGINT;
  actual_verified BIGINT;
BEGIN
  SELECT count(*),
         count(*) FILTER (WHERE disposition='import'),
         count(*) FILTER (WHERE disposition='archive'),
         count(*) FILTER (WHERE disposition='quarantine'),
         count(*) FILTER (WHERE verified)
  INTO actual_receipts, actual_imported, actual_archived, actual_quarantined, actual_verified
  FROM public.v1_domain_import_receipts
  WHERE import_version=NEW.import_version AND archive_run_id=NEW.archive_run_id;
  IF ROW(NEW.receipt_count,NEW.imported_count,NEW.archived_count,NEW.quarantined_count,NEW.verified_count)
     IS DISTINCT FROM ROW(actual_receipts,actual_imported,actual_archived,actual_quarantined,actual_verified) THEN
    RAISE EXCEPTION 'V1 domain import reconciliation counts do not match receipts' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: aicrm_validate_media_miniprogram_import_ledger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aicrm_validate_media_miniprogram_import_ledger() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  preflight_state TEXT;
  preflight_url_only_decision TEXT;
BEGIN
  SELECT state, url_only_decision
    INTO preflight_state, preflight_url_only_decision
    FROM public.media_miniprogram_import_preflights
    WHERE id = NEW.preflight_id
    FOR UPDATE;
  IF NOT FOUND OR preflight_state <> 'ready' THEN
    RAISE EXCEPTION 'media miniprogram import ledger requires a ready preflight' USING ERRCODE = '23514';
  END IF;
  IF NEW.disposition = 'migrated' AND NOT EXISTS (
    SELECT 1 FROM public.media_miniprograms
    WHERE id = NEW.target_miniprogram_id AND legacy_source_id = NEW.legacy_source_id
  ) THEN
    RAISE EXCEPTION 'media miniprogram import ledger target/source mismatch' USING ERRCODE = '23514';
  END IF;
  IF NEW.disposition = 'migrated' AND NOT EXISTS (
    SELECT 1 FROM public.media_miniprograms
    WHERE id = NEW.target_miniprogram_id AND
      thumbnail_media_id = '' AND thumbnail_media_expires_at IS NULL
  ) THEN
    RAISE EXCEPTION 'media miniprogram import ledger target contains provider cache state' USING ERRCODE = '23514';
  END IF;
  IF NEW.image_disposition IN ('remapped', 'rebuilt') AND NOT EXISTS (
    SELECT 1 FROM public.media_miniprograms
    WHERE id = NEW.target_miniprogram_id AND thumbnail_image_id = NEW.target_media_image_id
  ) THEN
    RAISE EXCEPTION 'media miniprogram import ledger image lineage mismatch' USING ERRCODE = '23514';
  END IF;
  IF NEW.image_disposition = 'rebuilt' AND NOT EXISTS (
    SELECT 1
    FROM public.media_images image
    JOIN public.media_image_blobs blob ON blob.image_id = image.id
    WHERE image.id = NEW.target_media_image_id AND
      image.checksum = NEW.rebuild_content_digest AND
      blob.checksum = NEW.rebuild_content_digest
  ) THEN
    RAISE EXCEPTION 'media miniprogram import ledger rebuild digest mismatch' USING ERRCODE = '23514';
  END IF;
  IF NEW.image_disposition = 'metadata_url_only' AND (
    (NEW.disposition = 'migrated' AND preflight_url_only_decision <> 'retain_metadata_without_fetch') OR
    (NEW.disposition = 'quarantined' AND preflight_url_only_decision <> 'quarantine_row') OR
    (NEW.disposition = 'migrated' AND NOT EXISTS (
      SELECT 1 FROM public.media_miniprograms
      WHERE id = NEW.target_miniprogram_id AND thumbnail_image_id IS NULL AND thumbnail_image_url <> ''
    ))
  ) THEN
    RAISE EXCEPTION 'media miniprogram import ledger URL-only decision mismatch' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


