    CONSTRAINT channel_acquisition_asset_bindi_reconcile_evidence_digest_check CHECK (((reconcile_evidence_digest IS NULL) OR (reconcile_evidence_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT channel_acquisition_asset_bindin_reconcile_receipt_digest_check CHECK (((reconcile_receipt_digest IS NULL) OR (reconcile_receipt_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
