    CONSTRAINT channel_acquisition_asset_bindings_asset_kind_check CHECK ((asset_kind = ANY (ARRAY['contact_way_qrcode'::text, 'customer_acquisition_link'::text]))),
    CONSTRAINT channel_acquisition_asset_bindings_asset_version_check CHECK ((asset_version > 0)),
    CONSTRAINT channel_acquisition_asset_bindings_assignee_wecom_userids_check CHECK (((cardinality(assignee_wecom_userids) >= 1) AND (cardinality(assignee_wecom_userids) <= 200))),
    CONSTRAINT channel_acquisition_asset_bindings_attempt_receipt_digest_check CHECK (((attempt_receipt_digest IS NULL) OR (attempt_receipt_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT channel_acquisition_asset_bindings_channel_code_check CHECK (((btrim(channel_code) = channel_code) AND ((char_length(channel_code) >= 1) AND (char_length(channel_code) <= 200)))),
    CONSTRAINT channel_acquisition_asset_bindings_channel_name_check CHECK (((btrim(channel_name) = channel_name) AND ((char_length(channel_name) >= 1) AND (char_length(channel_name) <= 200)))),
    CONSTRAINT channel_acquisition_asset_bindings_channel_revision_check CHECK ((channel_revision > 0)),
    CONSTRAINT channel_acquisition_asset_bindings_channel_status_check CHECK ((channel_status = 'active'::text)),
    CONSTRAINT channel_acquisition_asset_bindings_check CHECK (((supersedes_version >= 0) AND (asset_version > supersedes_version))),
    CONSTRAINT channel_acquisition_asset_bindings_envelope_fingerprint_check CHECK ((envelope_fingerprint ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT channel_acquisition_asset_bindings_fence_check CHECK ((fence >= 0)),
    CONSTRAINT channel_acquisition_asset_bindings_generation_check CHECK ((generation > 0)),
    CONSTRAINT channel_acquisition_asset_bindings_idempotency_digest_check CHECK ((idempotency_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT channel_acquisition_asset_bindings_queue_receipt_digest_check CHECK (((queue_receipt_digest IS NULL) OR (queue_receipt_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
