    CONSTRAINT channel_acquisition_asset_bindings_scene_value_check CHECK (((btrim(scene_value) = scene_value) AND (char_length(scene_value) <= 512))),
    CONSTRAINT channel_acquisition_asset_bindings_snapshot_digest_check CHECK ((snapshot_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT channel_acquisition_asset_bindings_state_check CHECK ((state = ANY (ARRAY['accepted'::text, 'queued'::text, 'attempted'::text, 'executed'::text, 'outcome_unknown'::text, 'reconciled'::text, 'final_failed'::text]))),
    CONSTRAINT channel_acquisition_asset_correlation_shape CHECK ((((corp_id IS NULL) AND (correlation_key IS NULL)) OR ((btrim(corp_id) = corp_id) AND ((char_length(corp_id) >= 1) AND (char_length(corp_id) <= 128)) AND (correlation_key ~ '^ch02_[A-Za-z0-9_-]{43}$'::text)))),
    CONSTRAINT channel_acquisition_asset_lease_shape CHECK ((((fence = 0) AND (lease_expires_at IS NULL)) OR ((fence > 0) AND (lease_expires_at IS NOT NULL)))),
    CONSTRAINT channel_acquisition_asset_scene_shape CHECK ((((asset_kind = 'contact_way_qrcode'::text) AND (scene_value <> ''::text)) OR (asset_kind = 'customer_acquisition_link'::text))),
    CONSTRAINT channel_acquisition_asset_state_shape CHECK ((((state = 'accepted'::text) AND (queue_receipt_id IS NULL) AND (queue_receipt_digest IS NULL) AND (river_job_id IS NULL) AND (fence = 0) AND (attempt_receipt_id IS NULL) AND (reconcile_receipt_id IS NULL)) OR ((state = 'queued'::text) AND (queue_receipt_id IS NOT NULL) AND (queue_receipt_digest IS NOT NULL) AND (river_job_id > 0) AND (fence = 0) AND (attempt_receipt_id IS NULL) AND (reconcile_receipt_id IS NULL)) OR ((state = 'attempted'::text) AND (queue_receipt_id IS NOT NULL) AND (river_job_id > 0) AND (fence > 0) AND (attempt_receipt_id IS NULL) AND (reconcile_receipt_id IS NULL)) OR ((state = ANY (ARRAY['executed'::text, 'final_failed'::text, 'outcome_unknown'::text])) AND (queue_receipt_id IS NOT NULL) AND (river_job_id > 0) AND (fence > 0) AND (attempt_receipt_id IS NOT NULL) AND (attempt_receipt_digest IS NOT NULL) AND (reconcile_receipt_id IS NULL)) OR ((state = 'reconciled'::text) AND (queue_receipt_id IS NOT NULL) AND (river_job_id > 0) AND (fence > 0) AND (attempt_receipt_id IS NOT NULL) AND (attempt_receipt_digest IS NOT NULL) AND (reconcile_receipt_id IS NOT NULL) AND (reconcile_receipt_digest IS NOT NULL) AND (reconcile_evidence_digest IS NOT NULL) AND (reconcile_resolution IS NOT NULL) AND (reconciled_at IS NOT NULL))))
);


