--

CREATE TABLE public.channel_acquisition_entrant_receipts (
    id bigint NOT NULL,
    inbox_id bigint NOT NULL,
    input_digest text NOT NULL,
    status text NOT NULL,
    effect_id bigint,
    channel_id bigint,
    asset_kind text,
    asset_version bigint,
    customer_id bigint,
    customer_event_id bigint,
    customer_event_occurred_at timestamp with time zone,
    occurred_at timestamp with time zone NOT NULL,
    reconciled_at timestamp with time zone,
    reconcile_reason text DEFAULT ''::text NOT NULL,
    reconcile_actor_id bigint,
    reconcile_key_digest text,
    reconcile_payload_digest text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT channel_acquisition_entrant_rece_reconcile_payload_digest_check CHECK (((reconcile_payload_digest IS NULL) OR (reconcile_payload_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT channel_acquisition_entrant_receipt_shape CHECK (((((effect_id IS NULL) AND (channel_id IS NULL) AND (asset_kind IS NULL) AND (asset_version IS NULL)) OR ((effect_id IS NOT NULL) AND (channel_id IS NOT NULL) AND (asset_kind = ANY (ARRAY['contact_way_qrcode'::text, 'customer_acquisition_link'::text])) AND (asset_version > 0))) AND (((customer_id IS NULL) AND (customer_event_id IS NULL) AND (customer_event_occurred_at IS NULL)) OR ((customer_id IS NOT NULL) AND (customer_event_id IS NOT NULL) AND (customer_event_occurred_at IS NOT NULL))) AND ((status <> ALL (ARRAY['attributed'::text, 'reconciled'::text])) OR ((effect_id IS NOT NULL) AND (customer_id IS NOT NULL))) AND ((status <> 'attributed'::text) OR (customer_event_id IS NOT NULL)) AND (((status <> 'reconciled'::text) AND (reconciled_at IS NULL) AND (reconcile_reason = ''::text) AND (reconcile_actor_id IS NULL) AND (reconcile_key_digest IS NULL) AND (reconcile_payload_digest IS NULL)) OR ((status = 'reconciled'::text) AND (reconciled_at IS NOT NULL) AND (reconcile_reason <> ''::text) AND (reconcile_actor_id IS NOT NULL) AND (reconcile_key_digest IS NOT NULL) AND (reconcile_payload_digest IS NOT NULL))))),
    CONSTRAINT channel_acquisition_entrant_receipts_input_digest_check CHECK ((input_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT channel_acquisition_entrant_receipts_reconcile_key_digest_check CHECK (((reconcile_key_digest IS NULL) OR (reconcile_key_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT channel_acquisition_entrant_receipts_reconcile_reason_check CHECK (((char_length(reconcile_reason) <= 200) AND (btrim(reconcile_reason) = reconcile_reason))),
    CONSTRAINT channel_acquisition_entrant_receipts_status_check CHECK ((status = ANY (ARRAY['correlated'::text, 'attributed'::text, 'pending_identity'::text, 'unmatched_asset'::text, 'ambiguous_asset'::text, 'conflict'::text, 'ignored'::text, 'reconciled'::text])))
);


