--
-- Name: cloud_campaign_touch_plans; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cloud_campaign_touch_plans (
    id text NOT NULL,
    campaign_code text NOT NULL,
    campaign_version bigint NOT NULL,
    source_kind text NOT NULL,
    customer_selection_id text,
    customer_selection_version text,
    segment_id bigint,
    audience_package_id bigint,
    audience_package_version bigint,
    member_snapshot_watermark timestamp with time zone,
    source_digest bytea NOT NULL,
    target_digest bytea NOT NULL,
    content_digest bytea NOT NULL,
    target_count integer NOT NULL,
    content_step_count integer NOT NULL,
    candidate_count integer NOT NULL,
    active_customer_count integer NOT NULL,
    inactive_excluded_count integer NOT NULL,
    policy_excluded_count integer NOT NULL,
    owner_actor_id bigint NOT NULL,
    local_only boolean DEFAULT true NOT NULL,
    provider_execution_eligible boolean DEFAULT false NOT NULL,
    runtime_executed boolean DEFAULT false NOT NULL,
    real_external_call_executed boolean DEFAULT false NOT NULL,
    delivery_proven boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT cloud_campaign_touch_plans_active_customer_count_check CHECK ((active_customer_count >= 0)),
    CONSTRAINT cloud_campaign_touch_plans_campaign_version_check CHECK ((campaign_version > 0)),
    CONSTRAINT cloud_campaign_touch_plans_candidate_count_check CHECK (((candidate_count >= 1) AND (candidate_count <= 1000))),
    CONSTRAINT cloud_campaign_touch_plans_content_digest_check CHECK ((octet_length(content_digest) = 32)),
    CONSTRAINT cloud_campaign_touch_plans_content_step_count_check CHECK (((content_step_count >= 1) AND (content_step_count <= 100))),
    CONSTRAINT cloud_campaign_touch_plans_delivery_proven_check CHECK ((NOT delivery_proven)),
    CONSTRAINT cloud_campaign_touch_plans_exclusions CHECK (((candidate_count = ((target_count + inactive_excluded_count) + policy_excluded_count)) AND (active_customer_count = (target_count + policy_excluded_count)))),
    CONSTRAINT cloud_campaign_touch_plans_id_check CHECK ((id ~ '^ctp_[0-9a-f]{64}$'::text)),
    CONSTRAINT cloud_campaign_touch_plans_inactive_excluded_count_check CHECK ((inactive_excluded_count >= 0)),
    CONSTRAINT cloud_campaign_touch_plans_local_only_check CHECK (local_only),
    CONSTRAINT cloud_campaign_touch_plans_owner_actor_id_check CHECK ((owner_actor_id > 0)),
    CONSTRAINT cloud_campaign_touch_plans_policy_excluded_count_check CHECK ((policy_excluded_count >= 0)),
    CONSTRAINT cloud_campaign_touch_plans_provider_execution_eligible_check CHECK ((NOT provider_execution_eligible)),
    CONSTRAINT cloud_campaign_touch_plans_real_external_call_executed_check CHECK ((NOT real_external_call_executed)),
    CONSTRAINT cloud_campaign_touch_plans_runtime_executed_check CHECK ((NOT runtime_executed)),
    CONSTRAINT cloud_campaign_touch_plans_source_digest_check CHECK ((octet_length(source_digest) = 32)),
    CONSTRAINT cloud_campaign_touch_plans_source_kind_check CHECK ((source_kind = ANY (ARRAY['customer_selection'::text, 'segment_members'::text, 'ai_audience_package_members'::text]))),
    CONSTRAINT cloud_campaign_touch_plans_source_shape CHECK ((((source_kind = 'customer_selection'::text) AND (customer_selection_id = 'local_selection'::text) AND (customer_selection_version = 'v1'::text) AND (segment_id IS NULL) AND (audience_package_id IS NULL) AND (audience_package_version IS NULL) AND (member_snapshot_watermark IS NULL)) OR ((source_kind = 'segment_members'::text) AND (customer_selection_id IS NULL) AND (customer_selection_version IS NULL) AND (segment_id > 0) AND (audience_package_id IS NULL) AND (audience_package_version IS NULL) AND (member_snapshot_watermark IS NOT NULL)) OR ((source_kind = 'ai_audience_package_members'::text) AND (customer_selection_id IS NULL) AND (customer_selection_version IS NULL) AND (segment_id IS NULL) AND (audience_package_id > 0) AND (audience_package_version > 0) AND (member_snapshot_watermark IS NOT NULL)))),
    CONSTRAINT cloud_campaign_touch_plans_target_count_check CHECK (((target_count >= 1) AND (target_count <= 1000))),
    CONSTRAINT cloud_campaign_touch_plans_target_digest_check CHECK ((octet_length(target_digest) = 32))
);


