-- Name: coupons; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.coupons (
    id bigint NOT NULL,
    name text NOT NULL,
    discount_amount_total bigint NOT NULL,
    currency character(3) DEFAULT 'CNY'::bpchar NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    total_issue_limit bigint NOT NULL,
    per_user_issue_limit bigint DEFAULT 1 NOT NULL,
    issued_count bigint DEFAULT 0 NOT NULL,
    claim_starts_at timestamp with time zone NOT NULL,
    claim_ends_at timestamp with time zone NOT NULL,
    validity_mode text NOT NULL,
    use_starts_at timestamp with time zone,
    use_ends_at timestamp with time zone,
    relative_validity_days integer,
    instructions text DEFAULT ''::text NOT NULL,
    first_claim_at timestamp with time zone,
    created_by bigint NOT NULL,
    updated_by bigint NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT coupons_actors CHECK (((created_by > 0) AND (updated_by > 0))),
    CONSTRAINT coupons_claim_fact CHECK ((((issued_count = 0) AND (first_claim_at IS NULL)) OR ((issued_count > 0) AND (first_claim_at IS NOT NULL)))),
    CONSTRAINT coupons_claim_range CHECK ((claim_ends_at > claim_starts_at)),
    CONSTRAINT coupons_currency CHECK ((currency = 'CNY'::bpchar)),
    CONSTRAINT coupons_discount CHECK ((discount_amount_total > 0)),
    CONSTRAINT coupons_instructions CHECK (((btrim(instructions) = instructions) AND (char_length(instructions) <= 200))),
    CONSTRAINT coupons_name CHECK (((btrim(name) = name) AND (name <> ''::text) AND (char_length(name) <= 45))),
    CONSTRAINT coupons_quantities CHECK (((total_issue_limit > 0) AND (per_user_issue_limit > 0) AND (per_user_issue_limit <= total_issue_limit) AND ((issued_count >= 0) AND (issued_count <= total_issue_limit)))),
    CONSTRAINT coupons_status CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text, 'stopped'::text, 'archived'::text]))),
    CONSTRAINT coupons_timestamps CHECK ((updated_at >= created_at)),
    CONSTRAINT coupons_validity CHECK ((((validity_mode = 'fixed_range'::text) AND (use_starts_at IS NOT NULL) AND (use_ends_at > use_starts_at) AND (relative_validity_days IS NULL)) OR ((validity_mode = 'relative_days'::text) AND (use_starts_at IS NULL) AND (use_ends_at IS NULL) AND (relative_validity_days > 0)))),
    CONSTRAINT coupons_version CHECK ((version > 0))
);


