--
-- Name: customer_merges; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_merges (
    id bigint NOT NULL,
    primary_customer_id bigint NOT NULL,
    merged_customer_id bigint NOT NULL,
    mode text NOT NULL,
    policy_version text NOT NULL,
    review_fingerprint bytea NOT NULL,
    fingerprint_key_version smallint NOT NULL,
    operated_by text NOT NULL,
    detail jsonb NOT NULL,
    merged_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT customer_merges_detail_closed CHECK (((jsonb_typeof(detail) = 'object'::text) AND (detail ?& ARRAY['policy_version'::text, 'mode'::text, 'fingerprint_version'::text, 'fingerprint'::text]) AND ((detail - ARRAY['policy_version'::text, 'mode'::text, 'fingerprint_version'::text, 'fingerprint'::text]) = '{}'::jsonb) AND (jsonb_typeof((detail -> 'policy_version'::text)) = 'string'::text) AND (jsonb_typeof((detail -> 'mode'::text)) = 'string'::text) AND (jsonb_typeof((detail -> 'fingerprint_version'::text)) = 'number'::text) AND (jsonb_typeof((detail -> 'fingerprint'::text)) = 'string'::text) AND ((detail ->> 'policy_version'::text) = policy_version) AND ((detail ->> 'mode'::text) = mode) AND ((detail ->> 'fingerprint_version'::text) = (fingerprint_key_version)::text) AND ((detail ->> 'fingerprint'::text) ~~ 'hmac-sha256-v%'::text))),
    CONSTRAINT customer_merges_distinct CHECK ((primary_customer_id <> merged_customer_id)),
    CONSTRAINT customer_merges_fingerprint_key_version CHECK ((fingerprint_key_version > 0)),
    CONSTRAINT customer_merges_mode CHECK ((mode = ANY (ARRAY['auto'::text, 'manual'::text]))),
    CONSTRAINT customer_merges_operator CHECK (((btrim(operated_by) <> ''::text) AND (char_length(operated_by) <= 200))),
    CONSTRAINT customer_merges_policy CHECK (((btrim(policy_version) <> ''::text) AND (char_length(policy_version) <= 200))),
    CONSTRAINT customer_merges_review_fingerprint_size CHECK ((octet_length(review_fingerprint) = 16))
);


