    content_snapshot jsonb NOT NULL,
    content_digest text NOT NULL,
    material_snapshot jsonb NOT NULL,
    material_digest text NOT NULL,
    execution_key_digest bytea NOT NULL,
    external_effect_id bigint NOT NULL,
    state text DEFAULT 'accepted'::text NOT NULL,
    provider_accepted boolean DEFAULT false NOT NULL,
    delivery_proven boolean DEFAULT false NOT NULL,
    provider_receipt_digest text,
    reconciliation_evidence_digest text,
    attempt_count integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    sender_userid_snapshot text,
    CONSTRAINT group_ops_executions_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT group_ops_executions_content_digest_check CHECK ((content_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT group_ops_executions_execution_key_digest_check CHECK ((octet_length(execution_key_digest) = 32)),
    CONSTRAINT group_ops_executions_material_digest_check CHECK ((material_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT group_ops_executions_node_position_check CHECK ((node_position > 0)),
    CONSTRAINT group_ops_executions_outcome CHECK ((((state = 'accepted'::text) AND (NOT provider_accepted) AND (NOT delivery_proven) AND (provider_receipt_digest IS NULL) AND (reconciliation_evidence_digest IS NULL) AND (attempt_count = 0)) OR ((state = 'provider_accepted'::text) AND provider_accepted AND (NOT delivery_proven) AND (provider_receipt_digest IS NOT NULL) AND (reconciliation_evidence_digest IS NULL) AND (attempt_count > 0)) OR ((state = 'delivery_proven'::text) AND provider_accepted AND delivery_proven AND (provider_receipt_digest IS NOT NULL) AND (reconciliation_evidence_digest IS NULL) AND (attempt_count > 0)) OR ((state = 'outcome_unknown'::text) AND (NOT delivery_proven) AND ((NOT provider_accepted) OR (provider_receipt_digest IS NOT NULL)) AND (reconciliation_evidence_digest IS NULL) AND (attempt_count > 0)) OR ((state = 'reconciled'::text) AND ((NOT delivery_proven) OR provider_accepted) AND ((NOT provider_accepted) OR (provider_receipt_digest IS NOT NULL)) AND (reconciliation_evidence_digest IS NOT NULL) AND (attempt_count > 0)) OR ((state = 'final_failed'::text) AND (NOT delivery_proven) AND ((NOT provider_accepted) OR (provider_receipt_digest IS NOT NULL)) AND (reconciliation_evidence_digest IS NULL) AND (attempt_count > 0)))),
    CONSTRAINT group_ops_executions_plan_revision_check CHECK ((plan_revision > 0)),
    CONSTRAINT group_ops_executions_provider_receipt_digest_check CHECK (((provider_receipt_digest IS NULL) OR (provider_receipt_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT group_ops_executions_reconciliation_evidence_digest_check CHECK (((reconciliation_evidence_digest IS NULL) OR (reconciliation_evidence_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT group_ops_executions_sender_snapshot CHECK (((sender_userid_snapshot IS NULL) OR (sender_userid_snapshot ~ '^[^[:space:]]{1,128}$'::text))),
    CONSTRAINT group_ops_executions_snapshots CHECK (((jsonb_typeof(content_snapshot) = 'object'::text) AND (jsonb_typeof(material_snapshot) = 'object'::text))),
    CONSTRAINT group_ops_executions_state_check CHECK ((state = ANY (ARRAY['accepted'::text, 'provider_accepted'::text, 'delivery_proven'::text, 'outcome_unknown'::text, 'reconciled'::text, 'final_failed'::text]))),
    CONSTRAINT group_ops_executions_target_digest_check CHECK ((target_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT group_ops_executions_target_reference CHECK (((target_reference ~ '^[A-Za-z0-9._:-]{1,128}$'::text) AND (POSITION(('://'::text) IN (target_reference)) = 0))),
    CONSTRAINT group_ops_executions_timestamps CHECK ((updated_at >= created_at))
);


