-- Name: identity_operation_receipts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.identity_operation_receipts (
    id bigint NOT NULL,
    operation text NOT NULL,
    idempotency_scope text NOT NULL,
    key_digest bytea NOT NULL,
    command_schema_version smallint NOT NULL,
    payload_hmac bytea NOT NULL,
    payload_hmac_key_version smallint NOT NULL,
    state text DEFAULT 'in_progress'::text NOT NULL,
    result_schema_version smallint NOT NULL,
    result_status text,
    result_customer_id bigint,
    result_merge_audit_id bigint,
    result_pending_event_id bigint,
    result_event_id bigint,
    result_policy_version text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT identity_receipts_command_schema_version CHECK ((command_schema_version > 0)),
    CONSTRAINT identity_receipts_completed_result CHECK ((((state = 'in_progress'::text) AND (result_status IS NULL) AND (result_customer_id IS NULL) AND (result_merge_audit_id IS NULL) AND (result_pending_event_id IS NULL) AND (result_event_id IS NULL) AND (result_policy_version IS NULL) AND (completed_at IS NULL)) OR ((state = 'completed'::text) AND (result_status IS NOT NULL) AND (completed_at IS NOT NULL) AND ((result_customer_id IS NULL) OR (result_customer_id > 0)) AND ((result_merge_audit_id IS NULL) OR (result_merge_audit_id > 0)) AND ((result_pending_event_id IS NULL) OR (result_pending_event_id > 0)) AND ((result_event_id IS NULL) OR (result_event_id > 0)) AND ((result_policy_version IS NULL) OR ((btrim(result_policy_version) <> ''::text) AND (char_length(result_policy_version) <= 200))) AND (((operation = 'bind'::text) AND (result_status = ANY (ARRAY['bound'::text, 'already_bound'::text, 'merged'::text, 'manual_review'::text, 'rejected'::text]))) OR ((operation = 'ingest'::text) AND (result_status = ANY (ARRAY['attributed'::text, 'pending'::text, 'conflict'::text]))) OR ((operation = 'merge_review_approve'::text) AND (result_status = 'approved'::text)) OR ((operation = 'merge_review_reject'::text) AND (result_status = 'rejected'::text)))))),
    CONSTRAINT identity_receipts_key_digest_size CHECK ((octet_length(key_digest) = 32)),
    CONSTRAINT identity_receipts_operation CHECK ((operation = ANY (ARRAY['bind'::text, 'ingest'::text, 'merge_review_approve'::text, 'merge_review_reject'::text]))),
    CONSTRAINT identity_receipts_payload_hmac_key_version CHECK ((payload_hmac_key_version > 0)),
    CONSTRAINT identity_receipts_payload_hmac_size CHECK ((octet_length(payload_hmac) = 32)),
    CONSTRAINT identity_receipts_result_schema_version CHECK ((result_schema_version > 0)),
    CONSTRAINT identity_receipts_result_status CHECK (((result_status IS NULL) OR (result_status = ANY (ARRAY['bound'::text, 'already_bound'::text, 'merged'::text, 'manual_review'::text, 'rejected'::text, 'attributed'::text, 'pending'::text, 'conflict'::text, 'approved'::text])))),
    CONSTRAINT identity_receipts_scope CHECK (((btrim(idempotency_scope) <> ''::text) AND (char_length(idempotency_scope) <= 256))),
    CONSTRAINT identity_receipts_state CHECK ((state = ANY (ARRAY['in_progress'::text, 'completed'::text])))
);


