CREATE TABLE public.internal_event_safe_export_rows (
    export_id text NOT NULL,
    row_index integer NOT NULL,
    event_id bigint NOT NULL,
    event_type text NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    dispatched boolean NOT NULL,
    consumer text,
    status text,
    attempt_count integer,
    completed_at timestamp with time zone,
    CONSTRAINT internal_event_safe_export_rows_check CHECK ((((consumer IS NULL) AND (status IS NULL) AND (attempt_count IS NULL) AND (completed_at IS NULL)) OR ((consumer IS NOT NULL) AND (btrim(consumer) = consumer) AND ((char_length(consumer) >= 1) AND (char_length(consumer) <= 200)) AND (status = ANY (ARRAY['pending'::text, 'processing'::text])) AND (attempt_count >= 0) AND (completed_at IS NULL)) OR ((consumer IS NOT NULL) AND (btrim(consumer) = consumer) AND ((char_length(consumer) >= 1) AND (char_length(consumer) <= 200)) AND (status = ANY (ARRAY['completed'::text, 'final_failed'::text, 'outcome_unknown'::text])) AND (attempt_count >= 0) AND (completed_at IS NOT NULL)))),
    CONSTRAINT internal_event_safe_export_rows_check1 CHECK (((consumer IS NULL) OR ((((((event_type = 'customer.tag_applied'::text) AND (consumer = 'automation.tag-trigger.v1'::text)) OR ((event_type = 'customer.tag_applied'::text) AND (consumer = 'stats.tag-applied.v1'::text))) OR ((event_type = 'operation_cycle.fact_recorded'::text) AND (consumer = 'operation-cycle.fact.v1'::text))) OR ((event_type = 'cloud_campaign.fact_recorded'::text) AND (consumer = 'cloud-campaign.fact.v1'::text))) OR ((event_type = 'outbound.campaign_handoff_fact_recorded'::text) AND (consumer = 'outbound-campaign-handoff.fact.v1'::text))))),
    CONSTRAINT internal_event_safe_export_rows_row_index_check CHECK (((row_index > 0) AND (row_index <= 10000)))
);


