CREATE TABLE public.media_miniprogram_operation_receipts (
    id bigint NOT NULL,
    operation text NOT NULL,
    actor_scope text NOT NULL,
    business_key text NOT NULL,
    key_digest bytea NOT NULL,
    payload_digest bytea NOT NULL,
    state text DEFAULT 'in_progress'::text NOT NULL,
    result_snapshot jsonb,
    created_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT media_miniprogram_receipts_actor CHECK (((actor_scope ~ '^admin:[1-9][0-9]*$'::text) AND (char_length(actor_scope) <= 200))),
    CONSTRAINT media_miniprogram_receipts_business CHECK (((business_key = 'create'::text) OR (business_key ~ '^[1-9][0-9]*$'::text))),
    CONSTRAINT media_miniprogram_receipts_completion CHECK ((((state = 'in_progress'::text) AND (result_snapshot IS NULL) AND (completed_at IS NULL)) OR ((state = 'completed'::text) AND (result_snapshot IS NOT NULL) AND (completed_at IS NOT NULL)))),
    CONSTRAINT media_miniprogram_receipts_key CHECK ((octet_length(key_digest) = 32)),
    CONSTRAINT media_miniprogram_receipts_operation CHECK ((operation = ANY (ARRAY['create'::text, 'update'::text, 'delete'::text, 'test-resolve'::text]))),
    CONSTRAINT media_miniprogram_receipts_payload CHECK ((octet_length(payload_digest) = 32)),
    CONSTRAINT media_miniprogram_receipts_state CHECK ((state = ANY (ARRAY['in_progress'::text, 'completed'::text])))
);


