--

CREATE TABLE public.media_miniprograms (
    id bigint NOT NULL,
    legacy_source_id bigint,
    name text NOT NULL,
    app_id text NOT NULL,
    page_path text NOT NULL,
    title text NOT NULL,
    thumbnail_image_url text DEFAULT ''::text NOT NULL,
    thumbnail_image_id bigint,
    thumbnail_media_id text DEFAULT ''::text NOT NULL,
    thumbnail_media_expires_at timestamp with time zone,
    enabled boolean DEFAULT true NOT NULL,
    created_by bigint NOT NULL,
    updated_by bigint NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT media_miniprograms_actors CHECK (((created_by > 0) AND (updated_by > 0))),
    CONSTRAINT media_miniprograms_app_id CHECK (((char_length(app_id) >= 1) AND (char_length(app_id) <= 120))),
    CONSTRAINT media_miniprograms_legacy_source CHECK (((legacy_source_id IS NULL) OR (legacy_source_id > 0))),
    CONSTRAINT media_miniprograms_name CHECK ((char_length(name) <= 200)),
    CONSTRAINT media_miniprograms_page_path CHECK (((char_length(page_path) >= 1) AND (char_length(page_path) <= 500))),
    CONSTRAINT media_miniprograms_thumbnail_cache CHECK (((char_length(thumbnail_media_id) <= 255) AND ((thumbnail_media_id <> ''::text) OR (thumbnail_media_expires_at IS NULL)))),
    CONSTRAINT media_miniprograms_thumbnail_image CHECK (((thumbnail_image_id IS NULL) OR (thumbnail_image_id > 0))),
    CONSTRAINT media_miniprograms_thumbnail_url CHECK ((char_length(thumbnail_image_url) <= 2048)),
    CONSTRAINT media_miniprograms_title CHECK (((char_length(title) >= 1) AND (char_length(title) <= 200))),
    CONSTRAINT media_miniprograms_version CHECK ((version > 0))
);


