-- Name: media_wecom_upload_preparations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.media_wecom_upload_preparations (
    id bigint NOT NULL,
    source_kind text NOT NULL,
    source_id bigint NOT NULL,
    source_digest text NOT NULL,
    provider_scope_digest text NOT NULL,
    upload_kind text NOT NULL,
    external_effect_id bigint NOT NULL,
    state text DEFAULT 'preparing'::text NOT NULL,
    provider_media_id text,
    provider_created_at timestamp with time zone,
    expires_at timestamp with time zone,
    provider_receipt_digest text,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT media_wecom_upload_preparations_media_id CHECK (((provider_media_id IS NULL) OR ((provider_media_id ~ '^[^[:space:]]+$'::text) AND ((char_length(provider_media_id) >= 1) AND (char_length(provider_media_id) <= 1024))))),
    CONSTRAINT media_wecom_upload_preparations_outcome CHECK ((((state = ANY (ARRAY['preparing'::text, 'retryable_failed'::text, 'outcome_unknown'::text, 'final_failed'::text])) AND (provider_media_id IS NULL) AND (provider_created_at IS NULL) AND (expires_at IS NULL) AND (provider_receipt_digest IS NULL)) OR ((state = ANY (ARRAY['ready'::text, 'expired'::text])) AND (provider_media_id IS NOT NULL) AND (provider_created_at IS NOT NULL) AND (expires_at > provider_created_at) AND (provider_receipt_digest IS NOT NULL)))),
    CONSTRAINT media_wecom_upload_preparations_provider_receipt_digest_check CHECK (((provider_receipt_digest IS NULL) OR (provider_receipt_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT media_wecom_upload_preparations_provider_scope_digest_check CHECK ((provider_scope_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT media_wecom_upload_preparations_source_digest_check CHECK ((source_digest ~ '^sha256:[0-9a-f]{64}$'::text)),
    CONSTRAINT media_wecom_upload_preparations_source_id_check CHECK ((source_id > 0)),
    CONSTRAINT media_wecom_upload_preparations_source_kind_check CHECK ((source_kind = ANY (ARRAY['image'::text, 'attachment'::text]))),
    CONSTRAINT media_wecom_upload_preparations_state_check CHECK ((state = ANY (ARRAY['preparing'::text, 'ready'::text, 'retryable_failed'::text, 'outcome_unknown'::text, 'final_failed'::text, 'expired'::text]))),
    CONSTRAINT media_wecom_upload_preparations_timestamps CHECK ((updated_at >= created_at)),
    CONSTRAINT media_wecom_upload_preparations_upload_kind_check CHECK ((upload_kind = ANY (ARRAY['image'::text, 'file'::text])))
);


