    material_id bigint NOT NULL,
    "position" integer NOT NULL,
    product_id text NOT NULL,
    sku_id text NOT NULL,
    sku_count bigint NOT NULL,
    on_aftersale_sku_count bigint,
    finish_aftersale_sku_count bigint,
