    CONSTRAINT order_wechat_shop_material_lines_aftersale CHECK (((aftersale_evidence_exact AND (on_aftersale_sku_count IS NOT NULL) AND (on_aftersale_sku_count >= 0) AND (finish_aftersale_sku_count IS NOT NULL) AND (finish_aftersale_sku_count >= 0) AND ((on_aftersale_sku_count + finish_aftersale_sku_count) <= sku_count) AND (remaining_sku_count = ((sku_count - on_aftersale_sku_count) - finish_aftersale_sku_count)) AND (((remaining_sku_count > 0) AND (readiness = 'ready'::text)) OR ((remaining_sku_count = 0) AND (readiness = 'no_remaining_count'::text)))) OR ((NOT aftersale_evidence_exact) AND (on_aftersale_sku_count IS NULL) AND (finish_aftersale_sku_count IS NULL) AND (remaining_sku_count IS NULL) AND (readiness = 'aftersale_evidence_missing'::text)))),
    CONSTRAINT order_wechat_shop_material_lines_amount CHECK (((sku_count > 0) AND (real_price_minor >= 0))),
    CONSTRAINT order_wechat_shop_material_lines_identifiers CHECK ((("position" > 0) AND (product_id <> ''::text) AND (btrim(product_id) = product_id) AND (char_length(product_id) <= 128) AND (sku_id <> ''::text) AND (btrim(sku_id) = sku_id) AND (char_length(sku_id) <= 128))),
    CONSTRAINT order_wechat_shop_material_lines_readiness CHECK ((readiness = ANY (ARRAY['ready'::text, 'aftersale_evidence_missing'::text, 'no_remaining_count'::text])))
);


