    CONSTRAINT order_wechat_shop_material_sync_requests_generation CHECK ((generation > 0)),
    CONSTRAINT order_wechat_shop_material_sync_requests_order CHECK (((provider_order_id <> ''::text) AND (btrim(provider_order_id) = provider_order_id) AND (char_length(provider_order_id) <= 128))),
