    CONSTRAINT order_wechat_shop_materials_provider_order_id CHECK (((provider_order_id <> ''::text) AND (btrim(provider_order_id) = provider_order_id) AND (char_length(provider_order_id) <= 128))),
    CONSTRAINT order_wechat_shop_materials_readiness CHECK ((readiness = ANY (ARRAY['ready'::text, 'provider_sync_required'::text, 'order_not_paid'::text, 'aftersale_evidence_missing'::text, 'no_refundable_line'::text]))),
    CONSTRAINT order_wechat_shop_materials_source CHECK ((((source = 'provider'::text) AND provider_verified AND (source_key_digest IS NULL) AND (readiness <> 'provider_sync_required'::text)) OR ((source = 'legacy_raw'::text) AND (NOT provider_verified) AND (source_key_digest IS NOT NULL) AND (readiness = 'provider_sync_required'::text)))),
    CONSTRAINT order_wechat_shop_materials_times CHECK (((version >= 1) AND (created_at <= updated_at) AND ((provider_paid_at IS NULL) OR (provider_created_at IS NULL) OR (provider_paid_at >= provider_created_at)) AND ((provider_updated_at IS NULL) OR (provider_created_at IS NULL) OR (provider_updated_at >= provider_created_at))))
);


