    CONSTRAINT order_wechat_shop_attempts_digests CHECK (((octet_length(args_digest) = 32) AND (octet_length(request_digest) = 32) AND ((evidence_digest IS NULL) OR (octet_length(evidence_digest) = 32)))),
    CONSTRAINT order_wechat_shop_attempts_numbers CHECK (((attempt_no > 0) AND (river_job_id > 0) AND (river_attempt > 0))),
