    refund_id bigint NOT NULL,
    provider_event_digest bytea NOT NULL,
    payload_digest bytea NOT NULL,
    provider_refund_digest bytea NOT NULL,
    outcome text,
    result_digest bytea,
    state text DEFAULT 'reserved'::text NOT NULL,
    received_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    contract_version text DEFAULT 'local/v1'::text NOT NULL,
    provider_aftersale_id text,
    provider_status text,
    river_job_id bigint,
    CONSTRAINT order_wechat_shop_callbacks_completion CHECK ((((contract_version = 'local/v1'::text) AND (provider_aftersale_id IS NULL) AND (provider_status IS NULL) AND (river_job_id IS NULL) AND (((state = 'reserved'::text) AND (outcome IS NULL) AND (result_digest IS NULL) AND (completed_at IS NULL)) OR ((state = 'completed'::text) AND (outcome = ANY (ARRAY['applied'::text, 'rejected'::text])) AND (result_digest IS NOT NULL) AND (completed_at IS NOT NULL)))) OR ((contract_version = 'provider/v2'::text) AND (provider_aftersale_id <> ''::text) AND (btrim(provider_aftersale_id) = provider_aftersale_id) AND (char_length(provider_aftersale_id) <= 128) AND (provider_status <> ''::text) AND (btrim(provider_status) = provider_status) AND (char_length(provider_status) <= 64) AND (((state = 'reserved'::text) AND (outcome IS NULL) AND (result_digest IS NULL) AND (river_job_id IS NULL) AND (completed_at IS NULL)) OR ((state = 'completed'::text) AND (outcome = 'query_queued'::text) AND (river_job_id > 0) AND (result_digest IS NOT NULL) AND (completed_at IS NOT NULL)))))),
    CONSTRAINT order_wechat_shop_callbacks_digests CHECK (((octet_length(provider_event_digest) = 32) AND (octet_length(payload_digest) = 32) AND (octet_length(provider_refund_digest) = 32) AND ((result_digest IS NULL) OR (octet_length(result_digest) = 32)))),
    CONSTRAINT order_wechat_shop_callbacks_state CHECK ((state = ANY (ARRAY['reserved'::text, 'completed'::text])))
);


