    CONSTRAINT order_wechat_shop_queries_evidence CHECK ((((outcome = 'not_confirmed'::text) AND (provider_refund_digest IS NULL) AND (amount_minor = 0) AND (currency = ''::text)) OR ((outcome = 'applied'::text) AND (provider_refund_digest IS NOT NULL) AND (amount_minor > 0) AND (currency = 'CNY'::text)) OR ((outcome = 'conflict'::text) AND (amount_minor >= 0) AND ((currency = ''::text) OR (currency ~ '^[A-Z]{3}$'::text))))),
    CONSTRAINT order_wechat_shop_queries_outcome CHECK ((outcome = ANY (ARRAY['not_confirmed'::text, 'applied'::text, 'conflict'::text])))
);


