-- Name: order_wechat_shop_refunds; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.order_wechat_shop_refunds (
    id bigint NOT NULL,
    order_id bigint NOT NULL,
    actor_id bigint NOT NULL,
    merchant_order_no text NOT NULL,
    out_refund_no text NOT NULL,
    amount_minor bigint NOT NULL,
    currency character(3) NOT NULL,
    reason_digest bytea NOT NULL,
    transaction_digest bytea NOT NULL,
    command_key_digest bytea NOT NULL,
    command_payload_digest bytea NOT NULL,
    source_ref_digest bytea NOT NULL,
    target_ref_digest bytea NOT NULL,
    payload_digest bytea NOT NULL,
    policy_version_digest bytea NOT NULL,
    provider_acceptance_digest bytea,
    provider_refund_digest bytea,
    settlement_receipt_digest bytea,
    state text DEFAULT 'accepted'::text NOT NULL,
    attempt_count bigint DEFAULT 0 NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    settled_at timestamp with time zone,
    contract_version text DEFAULT 'local/v1'::text NOT NULL,
    provider_order_id text,
    product_id text,
    sku_id text,
    refund_count bigint,
    unit_price_minor bigint,
    reason_code text,
    material_evidence_digest bytea,
    provider_aftersale_id text,
    CONSTRAINT order_wechat_shop_refunds_actor CHECK ((actor_id > 0)),
    CONSTRAINT order_wechat_shop_refunds_amount CHECK ((amount_minor > 0)),
    CONSTRAINT order_wechat_shop_refunds_currency CHECK ((currency = 'CNY'::bpchar)),
    CONSTRAINT order_wechat_shop_refunds_digests CHECK (((octet_length(reason_digest) = 32) AND (octet_length(transaction_digest) = 32) AND (octet_length(command_key_digest) = 32) AND (octet_length(command_payload_digest) = 32) AND (octet_length(source_ref_digest) = 32) AND (octet_length(target_ref_digest) = 32) AND (octet_length(payload_digest) = 32) AND (octet_length(policy_version_digest) = 32) AND ((provider_acceptance_digest IS NULL) OR (octet_length(provider_acceptance_digest) = 32)) AND ((provider_refund_digest IS NULL) OR (octet_length(provider_refund_digest) = 32)) AND ((settlement_receipt_digest IS NULL) OR (octet_length(settlement_receipt_digest) = 32)))),
    CONSTRAINT order_wechat_shop_refunds_evidence CHECK ((((state = 'provider_accepted'::text) AND (provider_acceptance_digest IS NOT NULL) AND (provider_refund_digest IS NULL) AND (settlement_receipt_digest IS NULL) AND (settled_at IS NULL)) OR ((state = 'succeeded'::text) AND (provider_refund_digest IS NOT NULL) AND (settlement_receipt_digest IS NOT NULL) AND (settled_at IS NOT NULL)) OR ((state = ANY (ARRAY['accepted'::text, 'executing'::text, 'outcome_unknown'::text, 'final_failed'::text])) AND (provider_acceptance_digest IS NULL) AND (provider_refund_digest IS NULL) AND (settlement_receipt_digest IS NULL) AND (settled_at IS NULL)))),
    CONSTRAINT order_wechat_shop_refunds_number CHECK ((out_refund_no ~ '^wsr_[a-f0-9]{32}$'::text)),
    CONSTRAINT order_wechat_shop_refunds_order_no CHECK (((btrim(merchant_order_no) = merchant_order_no) AND (merchant_order_no <> ''::text) AND (char_length(merchant_order_no) <= 200))),
    CONSTRAINT order_wechat_shop_refunds_provider_contract CHECK ((((contract_version = 'local/v1'::text) AND (provider_order_id IS NULL) AND (product_id IS NULL) AND (sku_id IS NULL) AND (refund_count IS NULL) AND (unit_price_minor IS NULL) AND (reason_code IS NULL) AND (material_evidence_digest IS NULL) AND (provider_aftersale_id IS NULL)) OR ((contract_version = 'provider/v2'::text) AND (provider_order_id <> ''::text) AND (btrim(provider_order_id) = provider_order_id) AND (char_length(provider_order_id) <= 128) AND (product_id <> ''::text) AND (btrim(product_id) = product_id) AND (char_length(product_id) <= 128) AND (sku_id <> ''::text) AND (btrim(sku_id) = sku_id) AND (char_length(sku_id) <= 128) AND (refund_count > 0) AND (refund_count <= 1000000) AND (unit_price_minor >= 0) AND (unit_price_minor <= 1000000000) AND (amount_minor <= (unit_price_minor * refund_count)) AND (reason_code = ANY (ARRAY['10000000'::text, '10000001'::text, '10000002'::text, '10000006'::text, '10000007'::text, '10000008'::text, '10000014'::text, '10000015'::text, '10000017'::text, '10000021'::text])) AND (octet_length(material_evidence_digest) = 32) AND (((state = ANY (ARRAY['accepted'::text, 'executing'::text, 'outcome_unknown'::text, 'final_failed'::text])) AND (provider_aftersale_id IS NULL)) OR ((state = ANY (ARRAY['provider_accepted'::text, 'succeeded'::text])) AND (provider_aftersale_id <> ''::text) AND (btrim(provider_aftersale_id) = provider_aftersale_id) AND (char_length(provider_aftersale_id) <= 128) AND (octet_length(provider_acceptance_digest) = 32)))))),
    CONSTRAINT order_wechat_shop_refunds_state CHECK ((state = ANY (ARRAY['accepted'::text, 'executing'::text, 'provider_accepted'::text, 'outcome_unknown'::text, 'succeeded'::text, 'final_failed'::text]))),
    CONSTRAINT order_wechat_shop_refunds_time CHECK (((updated_at >= created_at) AND ((settled_at IS NULL) OR (settled_at >= created_at)))),
    CONSTRAINT order_wechat_shop_refunds_version CHECK (((attempt_count >= 0) AND (version > 0)))
);


