    CONSTRAINT radar_link_idempotency_actor_check CHECK ((actor_id > 0)),
    CONSTRAINT radar_link_idempotency_completion_check CHECK ((((state = 'reserved'::text) AND (result_link_id IS NULL) AND (result_public_code IS NULL) AND (result_name IS NULL) AND (result_title IS NULL) AND (result_destination_url IS NULL) AND (result_cover_image_id IS NULL) AND (result_attachment_id IS NULL) AND (result_status IS NULL) AND (result_version IS NULL) AND (result_created_by IS NULL) AND (result_updated_by IS NULL) AND (result_created_at IS NULL) AND (result_updated_at IS NULL) AND (completed_at IS NULL)) OR ((state = 'completed'::text) AND (result_link_id IS NOT NULL) AND (result_public_code IS NOT NULL) AND (result_name IS NOT NULL) AND (result_title IS NOT NULL) AND (result_destination_url IS NOT NULL) AND (result_status IS NOT NULL) AND (result_version IS NOT NULL) AND (result_created_by IS NOT NULL) AND (result_updated_by IS NOT NULL) AND (result_created_at IS NOT NULL) AND (result_updated_at IS NOT NULL) AND (completed_at IS NOT NULL)))),
