    CONSTRAINT radar_link_idempotency_result_ids_check CHECK ((((result_link_id IS NULL) OR (result_link_id > 0)) AND ((result_cover_image_id IS NULL) OR (result_cover_image_id > 0)) AND ((result_attachment_id IS NULL) OR (result_attachment_id > 0)) AND ((result_version IS NULL) OR (result_version >= 1)) AND ((result_created_by IS NULL) OR (result_created_by > 0)) AND ((result_updated_by IS NULL) OR (result_updated_by > 0)))),
    CONSTRAINT radar_link_idempotency_result_name_check CHECK (((result_name IS NULL) OR (((char_length(result_name) >= 1) AND (char_length(result_name) <= 120)) AND (btrim(result_name) = result_name)))),
    CONSTRAINT radar_link_idempotency_result_public_code_check CHECK (((result_public_code IS NULL) OR (result_public_code ~ '^rd_[A-Za-z0-9_-]{22}$'::text))),
    CONSTRAINT radar_link_idempotency_result_status_check CHECK (((result_status IS NULL) OR (result_status = ANY (ARRAY['draft'::text, 'enabled'::text, 'disabled'::text])))),
    CONSTRAINT radar_link_idempotency_result_timestamp_check CHECK (((result_updated_at IS NULL) OR ((result_created_at IS NOT NULL) AND (result_updated_at >= result_created_at)))),
    CONSTRAINT radar_link_idempotency_result_title_check CHECK (((result_title IS NULL) OR (((char_length(result_title) >= 1) AND (char_length(result_title) <= 200)) AND (btrim(result_title) = result_title)))),
    CONSTRAINT radar_link_idempotency_result_url_check CHECK (((result_destination_url IS NULL) OR (((octet_length(result_destination_url) >= 1) AND (octet_length(result_destination_url) <= 2048)) AND (result_destination_url ~~ 'https://%'::text) AND (btrim(result_destination_url) = result_destination_url)))),
    CONSTRAINT radar_link_idempotency_state_check CHECK ((state = ANY (ARRAY['reserved'::text, 'completed'::text]))),
    CONSTRAINT radar_link_idempotency_timestamp_order_check CHECK (((completed_at IS NULL) OR (completed_at >= created_at)))
);


