--
-- Name: segment_refresh_receipts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.segment_refresh_receipts (
    id bigint NOT NULL,
    idempotency_scope text NOT NULL,
    idempotency_key text NOT NULL,
    segment_id bigint NOT NULL,
    state text DEFAULT 'reserved'::text NOT NULL,
    river_job_id bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    accepted_at timestamp with time zone,
    CONSTRAINT segment_refresh_receipts_acceptance CHECK ((((state = 'reserved'::text) AND (river_job_id IS NULL) AND (accepted_at IS NULL)) OR ((state = 'accepted'::text) AND (river_job_id IS NOT NULL) AND (river_job_id > 0) AND (accepted_at IS NOT NULL)))),
    CONSTRAINT segment_refresh_receipts_key CHECK (((btrim(idempotency_key) = idempotency_key) AND ((char_length(idempotency_key) >= 16) AND (char_length(idempotency_key) <= 128)))),
    CONSTRAINT segment_refresh_receipts_scope CHECK (((btrim(idempotency_scope) = idempotency_scope) AND (idempotency_scope <> ''::text) AND (char_length(idempotency_scope) <= 200))),
    CONSTRAINT segment_refresh_receipts_state CHECK ((state = ANY (ARRAY['reserved'::text, 'accepted'::text])))
);


