-- Name: segments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.segments (
    id bigint NOT NULL,
    name text NOT NULL,
    definition jsonb NOT NULL,
    refresh_mode text DEFAULT 'manual'::text NOT NULL,
    refresh_cron text,
    member_count bigint DEFAULT 0 NOT NULL,
    refreshed_at timestamp with time zone,
    refresh_status text DEFAULT 'idle'::text NOT NULL,
    created_by bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    lifecycle_status text DEFAULT 'active'::text NOT NULL,
    archived_at timestamp with time zone,
    archived_by text,
    CONSTRAINT segments_archive_pair CHECK ((((lifecycle_status = 'active'::text) AND (archived_at IS NULL) AND (archived_by IS NULL)) OR ((lifecycle_status = 'archived'::text) AND (archived_at IS NOT NULL) AND (archived_by IS NOT NULL) AND (btrim(archived_by) = archived_by) AND (archived_by <> ''::text) AND (char_length(archived_by) <= 200)))),
    CONSTRAINT segments_definition_object CHECK ((jsonb_typeof(definition) = 'object'::text)),
    CONSTRAINT segments_lifecycle_status CHECK ((lifecycle_status = ANY (ARRAY['active'::text, 'archived'::text]))),
    CONSTRAINT segments_member_count_nonnegative CHECK ((member_count >= 0)),
    CONSTRAINT segments_name_not_blank CHECK (((btrim(name) <> ''::text) AND (char_length(name) <= 200))),
    CONSTRAINT segments_refresh_cron CHECK ((((refresh_mode = 'manual'::text) AND (refresh_cron IS NULL)) OR ((refresh_mode = 'scheduled'::text) AND (refresh_cron IS NOT NULL) AND (btrim(refresh_cron) <> ''::text)))),
    CONSTRAINT segments_refresh_mode CHECK ((refresh_mode = ANY (ARRAY['manual'::text, 'scheduled'::text]))),
    CONSTRAINT segments_refresh_status CHECK ((refresh_status = ANY (ARRAY['idle'::text, 'running'::text, 'failed'::text])))
);


