    CONSTRAINT service_period_member_views_columns_unique CHECK (((cardinality(array_positions(columns, 'entitlement_id'::text)) <= 1) AND (cardinality(array_positions(columns, 'product_id'::text)) <= 1) AND (cardinality(array_positions(columns, 'state'::text)) <= 1) AND (cardinality(array_positions(columns, 'version'::text)) <= 1) AND (cardinality(array_positions(columns, 'granted_at'::text)) <= 1) AND (cardinality(array_positions(columns, 'revoked_at'::text)) <= 1) AND (cardinality(array_positions(columns, 'display_name'::text)) <= 1) AND (cardinality(array_positions(columns, 'masked_mobile'::text)) <= 1))),
    CONSTRAINT service_period_member_views_name CHECK (((btrim(name) = name) AND (name <> ''::text) AND (char_length(name) <= 200))),
    CONSTRAINT service_period_member_views_sort CHECK ((sort = 'granted_at_desc'::text)),
    CONSTRAINT service_period_member_views_source_not_self CHECK (((source_view_id IS NULL) OR (source_view_id <> id))),
    CONSTRAINT service_period_member_views_source_positive CHECK (((source_view_id IS NULL) OR (source_view_id > 0))),
    CONSTRAINT service_period_member_views_state CHECK ((state = ANY (ARRAY['active'::text, 'revoked'::text, 'all'::text]))),
    CONSTRAINT service_period_member_views_timestamps CHECK ((updated_at >= created_at)),
    CONSTRAINT service_period_member_views_version CHECK ((version >= 1))
);


