    member_ref text NOT NULL,
    service_product_id bigint NOT NULL,
    customer_id bigint NOT NULL,
    state text DEFAULT 'active'::text NOT NULL,
    source text NOT NULL,
    starts_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone,
    expired_at timestamp with time zone,
    removed_at timestamp with time zone,
    remark text,
    alliance text,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    pe01_lineage_version text,
    paid_order_id bigint,
    entitlement_id bigint,
    settlement_receipt_digest bytea,
    CONSTRAINT service_period_members_alliance CHECK (((alliance IS NULL) OR ((btrim(alliance) = alliance) AND (alliance <> ''::text) AND (char_length(alliance) <= 120)))),
    CONSTRAINT service_period_members_expiry CHECK (((expires_at IS NULL) OR (expires_at >= starts_at))),
    CONSTRAINT service_period_members_lifecycle CHECK ((((state = 'active'::text) AND (expired_at IS NULL) AND (removed_at IS NULL)) OR ((state = 'expired'::text) AND (expired_at IS NOT NULL) AND (expired_at >= starts_at) AND (removed_at IS NULL)) OR ((state = 'removed'::text) AND (removed_at IS NOT NULL) AND (removed_at >= starts_at)))),
    CONSTRAINT service_period_members_pe01_lineage CHECK (((pe01_lineage_version IS NULL) OR ((pe01_lineage_version = 'pe01/v1'::text) AND (source = 'paid_order'::text) AND (paid_order_id IS NOT NULL) AND (entitlement_id IS NOT NULL) AND (settlement_receipt_digest IS NOT NULL) AND (octet_length(settlement_receipt_digest) = 32)))),
    CONSTRAINT service_period_members_ref CHECK ((member_ref ~ '^spm_[A-Za-z0-9_-]{22}$'::text)),
    CONSTRAINT service_period_members_remark CHECK (((remark IS NULL) OR ((btrim(remark) = remark) AND (remark <> ''::text) AND (char_length(remark) <= 500)))),
    CONSTRAINT service_period_members_source CHECK ((source = ANY (ARRAY['manual'::text, 'paid_order'::text]))),
    CONSTRAINT service_period_members_state CHECK ((state = ANY (ARRAY['active'::text, 'expired'::text, 'removed'::text]))),
    CONSTRAINT service_period_members_timestamps CHECK (((updated_at >= created_at) AND (created_at >= starts_at))),
    CONSTRAINT service_period_members_version CHECK ((version >= 1))
);


