    CONSTRAINT wecom_tag_effects_reconcile_evidence_digest_check CHECK (((reconcile_evidence_digest IS NULL) OR (reconcile_evidence_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT wecom_tag_effects_reconcile_receipt_digest_check CHECK (((reconcile_receipt_digest IS NULL) OR (reconcile_receipt_digest ~ '^sha256:[0-9a-f]{64}$'::text))),
    CONSTRAINT wecom_tag_effects_reconcile_resolution_check CHECK (((reconcile_resolution IS NULL) OR (reconcile_resolution = ANY (ARRAY['provider_applied'::text, 'provider_not_applied'::text])))),
    CONSTRAINT wecom_tag_effects_state_check CHECK ((state = ANY (ARRAY['accepted'::text, 'queued'::text, 'executed'::text, 'outcome_unknown'::text, 'reconciled'::text, 'final_failed'::text]))),
    CONSTRAINT wecom_tag_effects_sync_trigger_check CHECK ((sync_trigger = ANY (ARRAY[''::text, 'manual'::text, 'due'::text])))
);


--
-- Name: wecom_v1_message_history; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.wecom_v1_message_history (
    id bigint NOT NULL,
    source_id bigint NOT NULL,
    sequence bigint,
    customer_id bigint,
    chat_type text NOT NULL,
    message_type text NOT NULL,
    content_masked text,
    original_send_time text NOT NULL,
    send_time_basis text NOT NULL,
    sent_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    source_payload_digest bytea NOT NULL,
    CONSTRAINT wecom_v1_message_history_check CHECK ((((send_time_basis = 'civil_unzoned'::text) AND (sent_at IS NULL)) OR ((send_time_basis = 'explicit_offset'::text) AND (sent_at IS NOT NULL)))),
    CONSTRAINT wecom_v1_message_history_customer_id_check CHECK ((customer_id > 0)),
    CONSTRAINT wecom_v1_message_history_send_time_basis_check CHECK ((send_time_basis = ANY (ARRAY['civil_unzoned'::text, 'explicit_offset'::text]))),
    CONSTRAINT wecom_v1_message_history_source_id_check CHECK ((source_id > 0)),
    CONSTRAINT wecom_v1_message_history_source_payload_digest_check CHECK ((octet_length(source_payload_digest) = 32))
);


--
-- Name: wecom_v1_message_history_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.wecom_v1_message_history ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.wecom_v1_message_history_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: whitelist_import_domain_receipts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.whitelist_import_domain_receipts (
    id bigint NOT NULL,
    run_id text NOT NULL,
    domain text NOT NULL,
    source_entity text NOT NULL,
    source_key_digest bytea NOT NULL,
    source_payload_digest bytea NOT NULL,
    target_entity text NOT NULL,
    target_id text,
    disposition text NOT NULL,
    reason text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT whitelist_import_domain_receipts_check CHECK ((((disposition = 'MIGRATE'::text) AND (target_id IS NOT NULL)) OR ((disposition <> 'MIGRATE'::text) AND (target_id IS NULL)))),
    CONSTRAINT whitelist_import_domain_receipts_disposition_check CHECK ((disposition = ANY (ARRAY['MIGRATE'::text, 'ARCHIVE_NOT_ON_V2'::text, 'CLEAR'::text, 'REJECT'::text]))),
    CONSTRAINT whitelist_import_domain_receipts_domain_check CHECK ((domain = ANY (ARRAY['identity'::text, 'product'::text, 'order'::text, 'questionnaire'::text, 'membership'::text, 'radar'::text, 'channel'::text, 'audience'::text, 'automation'::text, 'hxc'::text]))),
    CONSTRAINT whitelist_import_domain_receipts_source_key_digest_check CHECK ((octet_length(source_key_digest) = 32)),
    CONSTRAINT whitelist_import_domain_receipts_source_payload_digest_check CHECK ((octet_length(source_payload_digest) = 32))
);


--
-- Name: whitelist_import_domain_receipts_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.whitelist_import_domain_receipts ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.whitelist_import_domain_receipts_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: whitelist_import_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.whitelist_import_runs (
    id text NOT NULL,
    source_digest bytea NOT NULL,
    state text NOT NULL,
    started_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    report jsonb,
    CONSTRAINT whitelist_import_runs_check CHECK ((((state = 'running'::text) AND (completed_at IS NULL) AND (report IS NULL)) OR ((state = ANY (ARRAY['completed'::text, 'failed'::text])) AND (completed_at IS NOT NULL) AND (report IS NOT NULL)))),
    CONSTRAINT whitelist_import_runs_id_check CHECK ((id ~ '^wli_[A-Za-z0-9_-]{8,80}$'::text)),
    CONSTRAINT whitelist_import_runs_source_digest_check CHECK ((octet_length(source_digest) = 32)),
    CONSTRAINT whitelist_import_runs_state_check CHECK ((state = ANY (ARRAY['running'::text, 'completed'::text, 'failed'::text])))
);


--
-- Name: whitelist_schema_version; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.whitelist_schema_version (
    singleton boolean DEFAULT true NOT NULL,
    version integer NOT NULL,
    name text NOT NULL,
    applied_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT whitelist_schema_version_name_check CHECK ((name = 'aicrm-v2-core'::text)),
    CONSTRAINT whitelist_schema_version_singleton_check CHECK (singleton),
    CONSTRAINT whitelist_schema_version_version_check CHECK ((version = 2))
);


